/bin/bash -c "python - <<'PY'
from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png').convert('RGB')).astype(float)
# ASCII threshold low values within ROI x 90-240 y 20-100
# output thresholded dark <90 and bright >170 separately at 2px
for mode in ['dark','bright','red']:
 print('\\nMODE',mode)
 for by in range(10,50):
  line=''
  for bx in range(45,120):
   p=im[by*2:by*2+2,bx*2:bx*2+2].mean((0,1))
   if mode=='dark': ch='#' if p.mean()<65 else ('+' if p.mean()<95 else ' ')
   elif mode=='bright': ch='#' if p.mean()>175 else ('+' if p.mean()>140 else ' ')
   else: ch='#' if (p[0]>p[1]*1.5 and p[0]>p[2]*2 and p[0]>60) else ('+' if p[0]>p[1]*1.2 and p[0]>p[2]*1.5 else ' ')
   line+=ch
  print(f'{by*2:3d} {line}')
 print('     '+''.join(str((i//10)%10) for i in range(45,120)))
 print('     '+''.join(str(i%10) for i in range(45,120)))
PY"
